const CONFIG = {
  clusterName: 'dev',
  lookbackHours: 24,
  restartWarningThreshold: 5,
  maxItemsPerSection: 25,
  maxEvents: 50,
};

const grouped = {};
for (const item of $input.all()) {
  const collection = item.json.collection || 'unknown';
  grouped[collection] ||= [];
  grouped[collection].push(unwrapToolResult(item.json.result));
}

const data = Object.fromEntries(Object.entries(grouped).map(([key, values]) => [key, normalizeList(values)]));
const findings = buildFindings(data);
const critical = findings.filter((finding) => finding.severity === 'critical');
const warnings = findings.filter((finding) => finding.severity === 'warning');
const info = buildInfo(data);
const overall = critical.length > 0 ? 'Needs attention' : warnings.length > 0 ? 'Warnings present' : 'Healthy';
const subject = `Daily cluster health digest: ${CONFIG.clusterName} - ${critical.length} critical, ${warnings.length} warnings`;
const html = renderHtml({ overall, critical, warnings, info });

return [{ json: { subject, html, text: stripHtml(html), criticalCount: critical.length, warningCount: warnings.length } }];

function buildFindings(data) {
  const findings = [];
  const since = Date.now() - CONFIG.lookbackHours * 60 * 60 * 1000;

  for (const event of normalizeList(data.events).slice(0, CONFIG.maxEvents)) {
    const type = event.type || event.eventType || event.reason;
    const timestamp = Date.parse(event.lastTimestamp || event.eventTime || event.metadata?.creationTimestamp || '') || Date.now();
    if (type !== 'Warning' || timestamp < since) continue;

    const involved = event.involvedObject || event.regarding || {};
    findings.push({
      severity: 'warning',
      namespace: event.metadata?.namespace || involved.namespace || 'cluster',
      resource: compactResource(involved.kind, involved.name),
      title: `${compactResource(involved.kind, involved.name)}: ${event.reason || 'Warning event'}`,
      detail: event.message || event.note || 'Kubernetes warning event',
      count: event.count || event.series?.count,
    });
  }

  for (const pod of normalizeList(data.pods)) {
    const ns = pod.metadata?.namespace || 'default';
    const name = pod.metadata?.name || 'unknown-pod';
    const phase = pod.status?.phase || 'Unknown';
    if (!['Running', 'Succeeded'].includes(phase)) {
      findings.push({ severity: phase === 'Failed' ? 'critical' : 'warning', namespace: ns, resource: `Pod/${name}`, title: `Pod/${name} is ${phase}`, detail: pod.status?.reason || pod.status?.message || 'Pod phase is not healthy' });
    }

    for (const status of pod.status?.containerStatuses || []) {
      const waiting = status.state?.waiting;
      if (waiting) {
        const reason = waiting.reason || 'Waiting';
        const severity = ['CrashLoopBackOff', 'ImagePullBackOff', 'ErrImagePull', 'CreateContainerConfigError'].includes(reason) ? 'critical' : 'warning';
        findings.push({ severity, namespace: ns, resource: `Pod/${name}`, title: `Pod/${name}/${status.name}: ${reason}`, detail: waiting.message || 'Container is waiting' });
      }

      if ((status.restartCount || 0) >= CONFIG.restartWarningThreshold) {
        findings.push({ severity: 'warning', namespace: ns, resource: `Pod/${name}`, title: `Pod/${name}/${status.name}: ${status.restartCount} restarts`, detail: `Restart count is at or above threshold ${CONFIG.restartWarningThreshold}` });
      }
    }
  }

  for (const deployment of normalizeList(data.deployments)) {
    const desired = deployment.spec?.replicas ?? 1;
    const available = deployment.status?.availableReplicas ?? 0;
    if (desired > available) {
      findings.push({ severity: available === 0 ? 'critical' : 'warning', namespace: deployment.metadata?.namespace || 'default', resource: `Deployment/${deployment.metadata?.name}`, title: `Deployment/${deployment.metadata?.name}: ${available}/${desired} replicas available`, detail: conditionMessage(deployment.status?.conditions) });
    }
  }

  for (const job of normalizeList(data.jobs)) {
    const startTime = Date.parse(job.status?.startTime || job.metadata?.creationTimestamp || '') || 0;
    if ((job.status?.failed || 0) > 0 && startTime >= since) {
      findings.push({ severity: 'warning', namespace: job.metadata?.namespace || 'default', resource: `Job/${job.metadata?.name}`, title: `Job/${job.metadata?.name}: ${job.status.failed} failed pod(s)`, detail: conditionMessage(job.status?.conditions) });
    }
  }

  for (const pvc of normalizeList(data.pvcs)) {
    if (pvc.status?.phase && pvc.status.phase !== 'Bound') {
      findings.push({ severity: 'warning', namespace: pvc.metadata?.namespace || 'default', resource: `PersistentVolumeClaim/${pvc.metadata?.name}`, title: `PVC/${pvc.metadata?.name}: ${pvc.status.phase}`, detail: 'PersistentVolumeClaim is not bound' });
    }
  }

  for (const node of normalizeList(data.nodes)) {
    const conditions = node.status?.conditions || [];
    const ready = conditions.find((condition) => condition.type === 'Ready');
    if (ready && ready.status !== 'True') {
      findings.push({ severity: 'critical', namespace: 'cluster', resource: `Node/${node.metadata?.name}`, title: `Node/${node.metadata?.name}: Ready=${ready.status}`, detail: ready.message || ready.reason || 'Node is not ready' });
    }

    for (const condition of conditions.filter((item) => ['DiskPressure', 'MemoryPressure', 'PIDPressure', 'NetworkUnavailable'].includes(item.type) && item.status === 'True')) {
      findings.push({ severity: 'warning', namespace: 'cluster', resource: `Node/${node.metadata?.name}`, title: `Node/${node.metadata?.name}: ${condition.type}`, detail: condition.message || condition.reason || 'Node pressure condition is active' });
    }
  }

  for (const app of normalizeList(data.argoApplications)) {
    const sync = app.status?.sync?.status;
    const health = app.status?.health?.status;
    if ((sync && sync !== 'Synced') || (health && health !== 'Healthy')) {
      findings.push({ severity: health === 'Degraded' ? 'critical' : 'warning', namespace: app.metadata?.namespace || 'argocd', resource: `Application/${app.metadata?.name}`, title: `Argo Application/${app.metadata?.name}: ${sync || 'Unknown sync'} / ${health || 'Unknown health'}`, detail: app.status?.conditions?.map((condition) => `${condition.type}: ${condition.message}`).join('; ') || 'Argo CD application is not healthy and synced' });
    }
  }

  for (const cert of normalizeList(data.certificates)) {
    const ready = findReadyCondition(cert);
    if (ready && ready.status !== 'True') {
      findings.push({ severity: 'warning', namespace: cert.metadata?.namespace || 'default', resource: `Certificate/${cert.metadata?.name}`, title: `Certificate/${cert.metadata?.name}: Ready=${ready.status}`, detail: ready.message || ready.reason || 'Certificate is not ready' });
    }
  }

  for (const secret of normalizeList(data.externalSecrets)) {
    const ready = findReadyCondition(secret);
    if (ready && ready.status !== 'True') {
      findings.push({ severity: 'warning', namespace: secret.metadata?.namespace || 'default', resource: `ExternalSecret/${secret.metadata?.name}`, title: `ExternalSecret/${secret.metadata?.name}: Ready=${ready.status}`, detail: ready.message || ready.reason || 'ExternalSecret is not ready' });
    }
  }

  return findings.sort((a, b) => severityRank(a.severity) - severityRank(b.severity) || (a.namespace || '').localeCompare(b.namespace || ''));
}

function buildInfo(data) {
  return [
    `Events collected: ${normalizeList(data.events).length}`,
    `Pods collected: ${normalizeList(data.pods).length}`,
    `Deployments collected: ${normalizeList(data.deployments).length}`,
    `Jobs collected: ${normalizeList(data.jobs).length}`,
    `PVCs collected: ${normalizeList(data.pvcs).length}`,
    `Nodes collected: ${normalizeList(data.nodes).length}`,
    `Argo applications collected: ${normalizeList(data.argoApplications).length}`,
    `Certificates collected: ${normalizeList(data.certificates).length}`,
    `ExternalSecrets collected: ${normalizeList(data.externalSecrets).length}`,
  ];
}

function renderHtml({ overall, critical, warnings, info }) {
  const generatedAt = new Date().toISOString();
  return `<!doctype html>
<html>
  <body style="font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif; color: #172033; line-height: 1.45;">
    <h1 style="font-size: 22px; margin-bottom: 4px;">Daily cluster health digest: ${escapeHtml(CONFIG.clusterName)}</h1>
    <p style="margin-top: 0; color: #5f6b7a;">Generated ${escapeHtml(generatedAt)} over the last ${CONFIG.lookbackHours} hours.</p>
    <p><strong>Overall:</strong> ${escapeHtml(overall)}</p>
    ${renderSection('Critical', critical, '#b42318')}
    ${renderSection('Warnings', warnings, '#b54708')}
    ${renderList('Collection summary', info)}
  </body>
</html>`;
}

function renderSection(title, items, color) {
  if (!items.length) return `<h2 style="font-size: 18px; color: ${color};">${title}</h2><p>None.</p>`;
  const rows = items.slice(0, CONFIG.maxItemsPerSection).map((item) => `<li style="margin-bottom: 10px;"><strong>${escapeHtml(item.namespace || 'cluster')} / ${escapeHtml(item.resource || item.title)}</strong><br>${escapeHtml(item.title)}<br><span style="color: #5f6b7a;">${escapeHtml(item.detail || '')}${item.count ? ` Count: ${escapeHtml(String(item.count))}` : ''}</span></li>`).join('');
  const omitted = items.length > CONFIG.maxItemsPerSection ? `<p>Omitted ${items.length - CONFIG.maxItemsPerSection} additional ${title.toLowerCase()} item(s).</p>` : '';
  return `<h2 style="font-size: 18px; color: ${color};">${title} (${items.length})</h2><ul>${rows}</ul>${omitted}`;
}

function renderList(title, items) {
  const rows = items.map((item) => `<li>${escapeHtml(String(item))}</li>`).join('');
  return `<h2 style="font-size: 18px;">${escapeHtml(title)}</h2><ul>${rows}</ul>`;
}

function unwrapToolResult(result) {
  if (!result) return [];
  if (Array.isArray(result)) return result;
  if (Array.isArray(result.content)) {
    const text = result.content.filter((item) => item.type === 'text' && typeof item.text === 'string').map((item) => item.text).join('\n').trim();
    if (text) return safeJson(text, text);
  }
  if (typeof result.result === 'string') return safeJson(result.result, result.result);
  if (typeof result.output === 'string') return safeJson(result.output, result.output);
  return result;
}

function normalizeList(value) {
  if (!value) return [];
  if (Array.isArray(value)) return value.flatMap((item) => normalizeList(item));
  if (Array.isArray(value.items)) return value.items;
  if (Array.isArray(value.resources)) return value.resources;
  if (Array.isArray(value.data)) return value.data;
  if (Array.isArray(value.result)) return value.result;
  return [];
}

function conditionMessage(conditions = []) {
  if (!Array.isArray(conditions) || conditions.length === 0) return '';
  return conditions.map((condition) => `${condition.type || 'Condition'}=${condition.status || 'Unknown'} ${condition.reason || ''} ${condition.message || ''}`.trim()).join('; ');
}

function findReadyCondition(resource) {
  return (resource.status?.conditions || []).find((condition) => condition.type === 'Ready');
}

function compactResource(kind, name) {
  if (!kind && !name) return 'resource';
  if (!kind) return name;
  if (!name) return kind;
  return `${kind}/${name}`;
}

function severityRank(severity) {
  return severity === 'critical' ? 0 : severity === 'warning' ? 1 : 2;
}

function safeJson(text, fallback) {
  try {
    return JSON.parse(text);
  } catch (_error) {
    return fallback;
  }
}

function escapeHtml(value) {
  return String(value ?? '').replace(/[&<>"']/g, (char) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[char]));
}

function stripHtml(html) {
  return html.replace(/<style[\s\S]*?<\/style>/gi, '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
}
